-- Generated by scripts/letters.ts from i18n/frFR/letters/: edit those, not this file.
-- letterTexts[id] = { greeting, body = { paragraph, ... }, signoff (its lines), ps = { paragraph, ... } }
local _, ns = ...
ns.letterTexts = {
  [1] = { greeting = "$N,", body = { "Je connaissais le nom d'Edwin VanCleef bien avant ses crimes. Hurlevent compte des murs qu'il a élevés de ses mains. Je suis soulagé que ce soit fini, et je n'ai pris aucun plaisir à vous le demander.", "Furlbrow voudrait rentrer chez lui avec sa famille. J'ai dû lui répondre : pas encore. Il voulait une date à noter, et je n'ai pas pu lui en donner. Il nous faut toujours des hommes sur les routes.", "La garde de nuit s'est passée sans alerte. Je ne m'y fie pas encore, et j'ai dit aux hommes de ne pas s'y fier non plus.", "Vous avez ma reconnaissance et celle de la milice. Je voulais que vous l'appreniez de moi." }, signoff = "Gryan Stoutmantle\nLa milice du peuple" },
  [2] = { greeting = "$gCher:Chère; $N,", body = { "Le mémorial est achevé, me dit-on, et le maître-maçon Marblesten est satisfait du granit d'Alterac que vous lui avez rapporté. J'avais demandé à notre roi ce que la guerre allait nous coûter. Il m'a répondu par du granit. Au maçon, je n'ai demandé qu'une chose : si le nom de Sully était gravé assez profondément pour rester lisible quand la pierre commencerait à s'user. La question est peut-être sotte. Elle comptait pour moi.", "J'ai rangé la lettre de Sully plusieurs fois. Chaque fois, l'un des garçons me demande ce que son père a écrit, et je la ressors. Le petit Edgar sait où je m'arrête, maintenant, et il m'attend là avant que je tourne la page.", "Cette lettre contient des choses que Sully ne m'a jamais dites à la maison. Il est étrange de les lire aujourd'hui, de sa main. J'aurais voulu pouvoir lui répondre.", "Merci de nous l'avoir rapportée. Je n'aurais pas supporté de perdre cela aussi." }, signoff = "Avec ma gratitude,\nSara Balloo" },
  [3] = { greeting = "$C,", body = { "La tête de Ramstein est au mur. Les chiens avalent de la pourriture vivante sans se plaindre. Ils refusent de manger sous cette tête. J'ai déplacé leurs gamelles.", "J'ai traqué Ramstein pendant des mois avant qu'il se réfugie dans Stratholme. L'avoir ici n'a rien arrangé à l'état de la ferme. Je n'y comptais pas. Je voulais sa mort, et vous y avez veillé.", "À votre arrivée à la ferme, vous n'étiez qu'un imbécile. Vous voilà parmi mes champions. Je le mets par écrit parce que vous ne le croiriez pas autrement. Tâchez de ne pas laisser cela enfler ce qui vous tient lieu de tête.", "Voilà qui est fait." }, signoff = "Nathanos" },
  [4] = { greeting = "$N,", body = { "Ma mère a été heureuse d'apprendre que tu avais rencontré Cairne, mon enfant, et sa première pensée a été de savoir si tu avais mangé avant de monter là-haut. Je n'ai pas su lui répondre, et elle trouve qu'un chef devrait savoir ce genre de choses.", "Elle va encore chercher elle-même son eau au puits. Quand j'ai proposé de porter sa cruche, elle m'a demandé si un chef n'avait rien de mieux à faire, et quand je lui ai dit que toi, tu l'avais portée pour elle, elle m'a répondu que j'aurais eu le temps d'aller chercher l'eau pendant que je le lui disais.", "Baine m'a fait parvenir des nouvelles de toi, et je les ai lues aux autres, près du feu. Les petits me les ont fait relire deux fois, et depuis, ils parlent des Rites chaque soir.", "Ma mère trouve que cette lettre a trop d'angles, comme les totems que je taille. Je lui ai dit que tu la lirais quand même." }, signoff = "Marche avec la Terre-mère,\nChef Hawkwind" },
  [5] = { greeting = "$gGamin:Gamine;,", body = { "La lentille est montée, le télescope marche, et les bottes sont de retour en rayon. Les clients ont arrêté de demander où elles étaient. Le meilleur silence que j'aie jamais payé.", "Écoute. Dizzywig a classé ta paie dans les frais de transport. Je lui ai fait corriger ça. Un chargement ne va pas tout seul dans un camp de pirates pour en ressortir avec les bonnes caisses. D'après mes comptes, je te dois donc la différence. Alors Dizzywig corrige les comptes. Pas la différence, $ggamin:gamine;. Les comptes.", "À Cabestan, tout le monde promet. Quatre-vingt-dix-neuf sur cent reviennent avec une histoire pour expliquer pourquoi ils n'ont pas pu. Toi, tu m'as rapporté mes bottes. Dans mon métier, c'est plus rare que l'or, et je m'y connais." }, signoff = "Gazlowe", ps = { "P.-S. Les pirates sont revenus sur la plage. Je leur ai envoyé une facture." } },
  [6] = { greeting = "$gMon cher:Ma chère; $N !", body = { "Bangalash ! Tout le camp en crie encore à table, le soir ! Sire Erlgadin jure que sa panthère était la proie la plus coriace, et Ajeck ne veut pas en entendre un mot. J'ai dû déplacer la bouilloire deux fois pour la sauver de leurs démonstrations.", "Erlgadin, Ajeck et moi avons tous beaucoup à dire sur ce tigre que vous avez abattu ! Il y avait une éternité que je guettais ce diable blanc, et j'ai bien gagné le droit d'en dire un mot !", "Barnil a lu mon récit de la chasse et m'a demandé où vous y étiez. Excellente question ! Je me suis si bien emballé sur mes propres tentatives que je vous avais complètement oublié. C'est arrangé : vous y êtes, et à la place qui vous revient !", "Sacrément bien joué ! À votre santé, nom d'une pipe ! À votre santé !" }, signoff = "Hemet Nesingwary" },
  [7] = { greeting = "Le bonjour de la grotte, $N !", body = { "Je suis toujours là où tu m'as trouvé. Je me sens tout à fait rétabli, promis. Enfin, presque. Il reste beaucoup d'araignées Tissebois entre le reste de Sombrevallon et moi, et un elfe raisonnable attend qu'elles aient l'air occupées.", "Dirania me fait dire que je suis assez remis pour rentrer à pied. Elle me rappelle aussi, chaque fois, qu'elle m'avait mis en garde contre ces araignées. Bon, elle n'a pas tort.", "Avant, j'allais la voir chaque jour à la même heure. Maintenant, elle sait où je suis du matin au soir, et je crois qu'elle préfère ça.", "Je m'attire toujours des ennuis, et quelqu'un réussit toujours à m'en sortir. D'habitude, c'est Dirania. Cette fois, c'était toi, avec cinq minutes pour y arriver. Merci." }, signoff = "Ton ami,\nIverron" },
  [8] = { greeting = "$N,", body = { "Le fruit que vous avez trouvé est la chose la plus intéressante de mon camp. Je le garde enveloppé, bien à l'écart de la terre, tant que je n'aurai pas compris ce qui s'est passé entre les deux. La faute en revient-elle au fruit, ou à la terre de Teldrassil ? Je préférerais que ce soit au fruit.", "Les graines de sylvain sont dans la terre spéciale, avec la terre rare que vous avez apportée de Dolanaar, et je vais les voir plus souvent qu'il n'est utile. On dit que la graine guettée met deux fois plus de temps à lever. Je n'ai constaté ni cela ni le contraire.", "Ce que je sais : la plante qui a porté ce fruit est une étrangère ici. Sa graine est peut-être venue de très loin. Ce que j'ignore : presque tout le reste. C'est une situation merveilleuse.", "Vous avez l'œil, $N. Merci de me l'avoir prêté." }, signoff = "Respectueusement,\nDenalan" },
  [9] = { greeting = "$N !", body = { "Je l'ai fait !! J'ai bu jusqu'à la dernière goutte, je suis passée juste devant la maison, et personne n'a rien vu. Rien du tout ! J'entendais mes propres pas, et j'étais sûre que tout le vignoble les entendait aussi.", "Tommy Joe était à la rivière, là où il est toujours. Évidemment, il ne me voyait pas non plus, alors j'ai dû dire son nom, et il a sursauté si haut que j'ai cru qu'il allait tomber à l'eau. Et puis il a ri, et moi aussi, et nous avons parlé jusqu'à ce que je revoie mes mains. J'ai couru jusqu'à la maison.", "Je sais que c'était mal de tromper ma famille. Je le referais sans hésiter !", "Je ne peux même pas remercier monsieur Pestle ni Mamie Stonefield, puisque je ne suis pas censée les connaître !", "Vous avez porté ma lettre à Tommy Joe. Celle-ci est pour vous." }, signoff = "Avec tout mon amour (pas ce genre d'amour-là, hein !),\nM." },
  [10] = { greeting = "$gMon petit:Ma petite; $N,", body = { "Le collier est revenu à sa place. Je dors avec. Que les kobolds viennent essayer.", "Ce Billy Maclure raconte à qui veut l'entendre que ma tourte était la meilleure qu'il ait jamais mangée. Bien sûr qu'elle l'était. Là n'est pas la question. La question, c'est qu'il m'a pris mon collier et qu'il a eu de la tourte pour sa peine, et maintenant la moitié de la forêt connaît ma tourte mieux que mon nom.", "Je t'ai donné les gants de mon mari parce qu'ils ne servaient à personne, pendus au crochet près de la porte. Il disait toujours qu'ils portaient chance, et puis il est parti pour sa dernière campagne sans eux. J'ai longtemps regardé ce crochet. Mieux vaut qu'ils passent la porte avec quelqu'un.", "Merci, va. Tu as bel et bien réchauffé le cœur d'une pauvre veuve, mais je le nierai devant n'importe quel Maclure." }, signoff = "Tatie Bernice", ps = { "P.-S. Je n'ai rien mis dans la tourte de Billy. J'y ai pensé." } },
  [11] = { greeting = "Bien le bonjour, $N !", body = { "Mon frère dit que la Shimmer Stout met plein d'étoiles dans les yeux et qu'avec elle, il y voit dans le noir. Le montagnard Kadrell m'a écrit de Thelsamar : elle donne les jambes légères, et il a l'impression de pouvoir voler. Un brasseur pourrait vivre de mots pareils, et c'est presque ce que je fais. Merci de la leur avoir portée, $gmon gars:ma fille;.", "Seulement voilà : elle n'est pas parfaite. Une stout qui donne à un nain l'impression de voler est une bonne stout. Une stout parfaite lui garde les pieds sur terre et le rend content d'y être. La chatoyante donne la bonne note. C'est le malt en dessous qui ne va pas, trop doux ou pas assez sombre, et j'ai trois petits brassins en route pour le savoir.", "Le brassage, j'ai ça dans le sang, et le sang est patient. J'y arriverai." }, signoff = "Rejold Barleybrew" },
  [12] = { greeting = "$N,", body = { "Bois : pas assez. Péons : endormis. Deux sous le même arbre, un sur le tas de bois, et un debout. Je ne les savais pas capables de ça.", "Ils se souviennent de toi, en tout cas. Le bruit a couru que tu traînais dans la vallée avec ma masse. Depuis, dès qu'un péon entend des pas, il est debout, la hache à la main, avant même d'avoir ouvert les yeux. Ça ne dure pas. C'est mieux que rien.", "Ils demandent si tu vas revenir. Je leur dis que oui. Je ne leur dis pas quand.", "Bon travail. Merci pour le coup de main." }, signoff = "Thazz'ril\nContremaître" },
  [13] = { greeting = "$N,", body = { "La nuit où vous m'avez apporté la tête, je n'ai pas dormi. Je suis resté assis au bord de l'eau, à écouter. Aucun tambour n'est venu des îles. Derrière moi, le village dormait, tout entier, comme autrefois. Je voulais l'entendre dormir.", "Du rivage, on voit les îles de l'Écho. Je sais toujours quelle plage était la mienne. Les îles ne sont pas à nous. Je les regarde quand même.", "Certains de ceux que vous avez combattus étaient des Darkspear, avant le maléfice. Ne les pleurez pas. C'est à nous de le faire, et nous l'avons fait." }, signoff = "Gadrin" },
  [14] = { greeting = "Jeune $N,", body = { "Les bêtes se désaltèrent de nouveau au puits Sabot-d’Hiver, avec autant d'ardeur qu'au premier jour. J'ai regardé les trotteurs des plaines s'y pencher, et les loups y descendre après eux, et chaque fois j'ai pensé qu'ils buvaient une eau que leurs semblables ont aidé à purifier. Ils ne le savent pas, mais la terre le sait, et moi aussi.", "Chaque totem a demandé quelque chose aux bêtes de Mulgore, jusqu'aux dents des alphas, et mon cœur en est encore lourd de mélancolie, et de fierté. Elles n'ont pas choisi de donner, et c'est vous qui avez porté leur don jusqu'aux puits.", "Quand le vent descend du nord, j'entends les esprits parler de vous." }, signoff = "Que les esprits soient avec vous,\nMull Thunderhorn" },
  [15] = { greeting = "$N,", body = { "Je vous écris pour accuser réception du rapport de Linnea, remis de votre main et sans délai. À Brill, la ponctualité est assez rare pour être remarquée.", "Le rapport disait ce qu'elle vous a dit. La Barricade contient le gros du Fléau, et quelques-uns passent quand même. Je l'ai classé avec tous ceux qui disent la même chose.", "Les fosses communes près de l'Antre de Garren ne sont pas sûres, mais les morts qui y reposent restent morts, et c'était bien là le but. Ils ont échappé à ce qu'on nous a fait subir. Il se trouve que j'ai un intérêt personnel à ce qu'il en reste ainsi, et votre travail chez les gnolls Poil-Putride l'a servi. Les apothicaires ont l'ichor. Ils ne m'en ont rien dit, ce qui, d'expérience, signifie qu'ils sont satisfaits.", "Le roi-liche et ses servants lancent des assauts incessants. Nous n'abandonnerons pas. Il ne passera pas." }, signoff = "Avec mes remerciements officiels,\nMagistrat Sevren" },
  [16] = { greeting = "$N,", body = { "La sentez-vous encore, cette vibration près des pierres dressées ? Oui ? Bien. Alors le lien est fait, et vous la sentirez de nouveau en bien des lieux.", "Les lignes telluriques vivaient autrefois dans les vieux livres. Aujourd'hui, elles percent l'herbe pour venir à notre rencontre. Don ou avertissement, c'est du savoir, et je compte bien en apprendre le plus possible avant que d'autres ne décident de ce que j'ai le droit de savoir.", "Rorian vous a remis votre relique en vous disant que les vents de votre patrie vous accompagneraient partout où vous iriez. Rorian y croit, et c'est une belle chose à croire. Je préfère ce qui se mesure.", "Ce sont des temps difficiles pour les Shen’dorei, et je sais ce que je veux d'abord : le savoir, puis le pouvoir." }, signoff = "Rendez l'inconnu connu,\nFalorne Tombevent" },
  [17] = { greeting = "$N,", body = { "La vue céleste est comme un muscle, et un muscle qu'on néglige s'affaiblit. Servez-vous-en sur la route, à l'auberge, sous la pluie. La plupart du temps, vous ne verrez rien qui vaille. Servez-vous-en quand même.", "Je garde la mienne ouverte un moment chaque soir, ici, au village, avant de dormir. Certains soirs, je saisis un mot ou deux, faibles comme une voix derrière un mur. D'autres soirs, rien. J'ai appris à ne pas en vouloir aux soirs silencieux. Ils font partie de l'entraînement.", "Je note ce que je saisis, même quand cela n'a aucun sens. Surtout dans ce cas. Les esprits ne se répètent pas pour nous faire plaisir.", "Nous aurons besoin de tous ceux qui savent écouter." }, signoff = "Patience,\nVentaari Vœu-Radieux" },
  [18] = { greeting = "$N,", body = { "J'ai envoyé Belathaan au sanctuaire d’Akir parce que la logique me le commandait. Parler coûte moins cher que saigner, et la paix moins cher que la guerre. Chaque ligne de ce raisonnement tenait. La secte y a répondu par une boîte. J'ai repris mes arguments bien des fois depuis, en cherchant l'erreur, et je ne la trouve que dans mon jugement sur la secte.", "Les Sculpte-vents avaient raison. L'écrire est pire que le dire.", "Les charmes que vous m'avez rapportés sont sous clé. Je les regarde moins qu'avant. Je n'ai pas oublié qui me les a rapportés.", "La secte a pesé notre prudence et l'a prise pour de la faiblesse. C'était un jugement, lui aussi, et le sien était bien plus erroné que le nôtre." }, signoff = "Elaadrin Trombecalme\nArchimagistère de l'Ordre suprême" },
  [19] = { greeting = "$N,", body = { "Je vous dois une meilleure réponse que celle que je vous ai donnée quand vous m'avez rapporté les charmes. « Une journée éprouvante », c'était bien peu dire.", "Les Sculpte-vents répondent au sang par le sang. Je l'ai dit toute ma vie, et je le pensais en vous envoyant au nord. Je le pense encore. Les novices que nous avons retrouvés dans les hautes-terres étaient des nôtres, et quelqu'un répondra de chacun d'eux.", "Mais je vous avais aussi demandé d'arrêter Belathaan sur la route, pour lui faire peur, et il n'est jamais revenu de cette route. Je vous ai dit que vous n'y étiez pour rien. C'était vrai. Je n'ai pas dit à qui revenait la faute, parce que je n'ai pas tranché. À Elaadrin, qui l'avait envoyé. À la secte, qui l'a tué. À moi, qui voulais qu'il ait peur. Sa mère était des nôtres.", "Ni oubli ni pardon. Lui non plus, je ne l'oublierai pas." }, signoff = "Ayessa Chantelaube\nGrande oracle des cieux des Sculpte-vents" },
  [20] = { greeting = "$N,", body = { "Le Barrage tient toujours ! Je descends à sa base chaque matin et chaque soir pour le regarder, et il tient toujours, et chaque fois je remercie les étoiles. Oh, ciel ! J'espère que vous ne saurez jamais ce que cette poudre aurait fait mouillée. J'en ai fait le calcul deux fois sur le papier, et puis j'ai arrêté de le faire !!", "Le détachement de sécurité est toujours sur le front de l'Alliance, et mon meilleur inspecteur avec lui. Il ne reste donc que moi, les montagnards qu'on veut bien me prêter, et l'eau. Maintenant, je frappe sur chaque tonneau que je croise. Sur chacun, sans exception.", "Personne d'autre n'est venu, et vous avez remué ce tonnelet comme on remue une soupe. Courage ou ignorance, je ne sais pas, et je vous suis reconnaissant de l'un comme de l'autre !", "Le Barrage est en sécurité, du moins pour l'instant, et tous ceux qui vivent en contrebas aussi." }, signoff = "Bien à vous, et un peu à la hâte,\nHinderweir VII\nIngénieur en chef, Barrage de Formepierre" },
  [21] = { greeting = "$N,", body = { "Pour une fois, voici une lettre de moi que vous n'aurez à porter nulle part.", "J'ai relu les trois réponses que vous m'avez rapportées plus souvent qu'un magistrat ne devrait relire quoi que ce soit. Hurlevent enverra des renforts dès que le roi en donnera l'ordre. La Marche de l'Ouest n'a pas d'hommes à offrir, et ses propres morts à enterrer. Sombre-Comté ne peut pas envoyer ses Veilleurs au-delà de la lisière de sa forêt. Chaque réponse est raisonnable. Ensemble, elles n'ont aucun sens.", "Comté-du-Lac tient, pour l'instant. Il y a de la trahison là-dessous, et je veux en avoir le cœur net. Bah. Je ne devrais pas réfléchir à voix haute, pas même sur le papier.", "Vous avez fait un long chemin pour un bourg qui ne vous devait rien, et chaque fois vous m'avez rapporté la vérité, même quand la vérité, c'était non. Merci." }, signoff = "Magistrat Solomon\nComté-du-Lac" },
  [22] = { greeting = "$N,", body = { "Hollee me dit que c'est vous qui m'avez fait sortir du chantier de fouilles, et que je n'étais pas, comme je le croyais alors, en train de me promener. Elle dit qu'il y avait des golems. Je me souviens d'une couche de sédiments tout à fait passionnante.", "Elle me dit aussi que mon fossile est allé à Darnassus, puis au Port de Menethil, ce qui fait plus de voyages que je n'en ai faits depuis des années, et qu'un certain Flagongut l'a maintenant, avec une pierre à lui. Formidable ! J'espère qu'il m'écrira. Qu'il m'écrira à moi, je veux dire, et pas à Hollee, même si c'est toujours Hollee qui semble tout recevoir.", "Je cherche mon pinceau à pierre. Je le mentionne seulement parce que je l'ai cherché pendant tout le temps où j'écrivais cette lettre, et qu'il m'a semblé impoli de ne pas le dire." }, signoff = "Avec mes remerciements et, je crois, mes excuses,\nProspecteur Remtravel" },
  [23] = { greeting = "$N,", body = { "Le NG-5 est arrivé en parfait état, c'est-à-dire qu'il ne t'a pas explosé à la figure en route, et je compte ça comme un succès pour tout le monde !", "Lomac est le meilleur chimiste qui m'ait jamais crié dessus. S'il t'a dit de me saluer, il le pensait. S'il a dit autre chose, il le pensait aussi, mais un peu moins.", "Tout est en place. Je ne te dirai pas le plan, d'abord parce qu'un plan raconté est un plan gâché, ensuite parce qu'il change chaque fois que je le regarde. Il y a des wagons. Il y a de la dynamite, qui n'est pas aussi dangereuse que tout le monde le croit. Il y a de la magie, des mixtures et de la mécanique qui travaillent ensemble, ce qui est tout l'intérêt de l'Assemblée et, franchement, de ma personne.", "Les elfes de la nuit me regardent encore comme si j'allais sauter. C'est de bonne guerre. Leur montrer qu'un gnome peut aider à sauver leurs forêts, c'est mon but, non, mon DEVOIR !" }, signoff = "Gaxim Rustfizzle\nAssemblée illuminée d'arcanologie, d'alchimie et de sciences d'ingénierie" },
  [24] = { greeting = "$N,", body = { "Le temps du deuil est venu, comme je l'avais dit, et il n'attend pas l'heure que j'aurais choisie. J'ai écrit à la famille de Teronis. C'est la lettre la plus courte que j'aie jamais écrite, et elle m'a pris toute la nuit.", "Vous l'avez trouvé, et vous avez trouvé ce qu'il cherchait en mourant. C'était plus que je n'osais espérer, et ce n'est pas assez.", "Les furbolgs n'ont pas toujours été nos ennemis. Quand j'étais jeune, je n'ai jamais tendu mon arc contre l'un d'eux. Aujourd'hui, je vous ai fait prendre la route de leurs camps et j'ai appelé cela défendre nos terres, et c'en était. Je veux seulement qu'il soit écrit quelque part que je me souviens d'un temps plus paisible." }, signoff = "Qu'Elune vous garde,\nRaene Wolfrunner" },
  [25] = { greeting = "$N,", body = { "J'ai prévenu la Grande prêtresse. Ce qui s'est dit entre nous, je le garde pour moi. Je dirai seulement que j'ai pris le chemin le plus long pour revenir au baraquement.", "Le coffre de Velinde est toujours dans le baraquement. Je ne parviens pas à le faire vider. Les Sentinelles croyaient qu'elle avait ses raisons de partir et qu'elle reviendrait quand elle le voudrait. Je le croyais aussi, et je vous l'ai dit. De toutes mes erreurs, c'est celle que j'aurais le moins voulu commettre.", "Cela me trouble de savoir que la Faux d'Elune n'est plus aux mains de ses servantes.", "Vous l'avez suivie à travers la moitié du monde sur la parole d'un livre qui s'écrit tout seul. Peu l'auraient fait. Je vous dois d'immenses remerciements." }, signoff = "Thyn'tel Bladeweaver" },
  [26] = { greeting = "$C,", body = { "Pardonnez ma colère, le jour de votre visite. Elle valait celle d'un kodo enragé, et vous n'aviez rien fait pour la mériter. La faute était mienne. J'ai envoyé des voyageurs sous la ville sans penser à qui d'autre pourrait les suivre, et deux amis ont payé ma négligence. Des sbires de Thrall, quels qu'ils soient. Je donnerais cher pour connaître leurs noms.", "En bas, je range ce que je peux. Nos amis des Tarides et de la forêt ont commencé leur propre ouvrage.", "Votre arrivée tombait au bon moment, et vous portiez la bonne marque. Je ne l'oublie pas. Dans une ville où si peu de gens sont ce qu'ils paraissent, il est réconfortant de connaître quelqu'un qui l'est." }, signoff = "Un ami de la Faille" },
  [27] = { greeting = "$N,", body = { "J'ai puisé ce que j'ai pu dans les chaînes de Bois-du-Bûcher que vous m'avez rapportées. Ce n'était pas assez. Je m'en doutais, et je crois bien l'avoir dit. Un petit échantillon reste un petit échantillon.", "Pourtant, je comprends le remède à présent, ou presque, et plus je le comprends, moins j'estime l'homme qui a jeté ce sort. Le Kirin Tor l'a laissé entrer dans ses salles. J'ai cessé de me demander comment.", "À Bois-du-Bûcher, ce sont toujours des hommes et des femmes le jour, et toujours autre chose quand le soleil se couche. Arugal a fait cela à tout un village avec un sort que n'importe quel apprenti aurait honte de signer. Ce que je lui pardonne le moins, ce n'est pas la malédiction. C'est la qualité du travail.", "Cela prendra plus longtemps que je ne pensais. Tout ce qui touche à Arugal prend plus longtemps que je ne pense. C'est peut-être son seul talent.", "Mes compliments, $N." }, signoff = "Dalar Dawnweaver\nLe Sépulcre" },
  [28] = { greeting = "$N,", body = { "Avant votre départ pour l'Ile de Fenris, j'ai rédigé deux rapports pour mes supérieurs. L'un disait que Thule Ravenclaw était mort. L'autre annonçait votre mort. Un commandant doit être prêt à l'un comme à l'autre. J'ai brûlé le second le jour où vous m'avez rapporté sa tête.", "Renferrel me dit que les énergies dégagées quand Thule est tombé ont été perçues jusqu'au Sépulcre. Il a raison. Je l'ai senti moi-même, et j'ai su ce que vous aviez fait avant qu'on me le dise.", "Le Fléau n'en a pas fini avec les Pins argentés. Les Poils-putrides tiennent toujours l'île, et ils ne la quitteront pas pour un mage mort. Mais ils ont perdu du terrain, et c'est par vous qu'ils l'ont perdu.", "Pour nous, votre valeur ne cesse de croître." }, signoff = "Grand exécuteur Hadrec\nLe Sépulcre" },
  [29] = { greeting = "$N,", body = { "Je ne suis pas doué pour les lettres. C'était elle qui avait les mots.", "Elle a tenu tête à trois hurans, à elle seule. Quand d'autres sont arrivés, j'en ai entraîné quelques-uns plus loin, et je me suis dit que c'était ça, le courage. Je ne me le dis plus.", "Le druide qui m'a trouvé sur la route m'a dit de me reposer. Je me suis reposé. Puis je suis retourné au camp où nous avions été séparés, et j'ai tué tous les hurans que j'y ai trouvés. Ça n'a pas aidé non plus.", "Vous l'avez trouvée, là où je n'ai pas pu. Je ne sais pas ce que vous avez vu là-bas, et je ne vous le demande pas.", "Merci, $C." }, signoff = "Mankrik" },
  [30] = { greeting = "$N,", body = { "J'ai dormi toute la nuit. Toute, du soir jusqu'à la première lumière sur la Cime des Anciens, et je me suis réveillée les mains ouvertes. J'avais oublié que le sommeil pouvait être si simple.", "Quand l'ancien a quitté le rêve, je suis restée, parce qu'il fallait que quelqu'un voie leurs visages. Je les ai vus. Ensuite, je n'ai plus pu cesser de les voir. Quatre visages, chaque nuit, tournés vers moi comme s'ils me connaissaient. Je me réveillais les poings fermés et les dents douloureuses. Ils ne viennent plus.", "Autrefois, ils étaient druides. Leur ordre voulait soigner les Tarides. J'y pense plus que je ne le voudrais. Il serait plus facile de les haïr s'ils avaient toujours été ce qu'ils sont devenus.", "La terre rêve encore, et mal. Ce n'était pas l'ouvrage d'une seule nuit. Mais mes rêves m'appartiennent de nouveau, et c'est vous qui les avez repris." }, signoff = "Nara Wildmane" },
  [31] = { greeting = "$N,", body = { "Les fortins ont tenu. Krom'zar a fait tout le chemin depuis Désolace pour se venger, et il est tombé sur vous.", "Barak, Verog, Hezrul, et puis Krom'zar. J'ai combattu les centaures presque toute ma vie, et je n'avais jamais vu quatre de leurs chefs tomber de la même main. Un centaure qui a l'esprit de mener les autres est rare, et ce sont ceux-là les plus dangereux. Vous avez pris les plus dangereux.", "Les Kolkar reviendront. Ils sont toujours revenus. Quand ils reviendront, ils se raconteront votre histoire, et j'espère qu'ils la raconteront mal.", "Gardez la tête haute, $N." }, signoff = "Regthar Deathgate" },
  [32] = { greeting = "$R,", body = { "Mangletooth écrit. <grogne> Mains pas faites pour la plume. Lisez quand même.", "Mangletooth a regardé votre course, depuis la cage. Vous couriez avec les zhévras. Le vent était jaloux, comme Mangletooth a dit. <grogne> L'esprit d'Agammagan répond encore à Mangletooth, barreaux ou pas. Aucune cage n'arrête ça. Souvenez-vous.", "Dos-hirsute plus faibles maintenant, grâce à vous et à Mangletooth. Et les Tranchecrins ne viennent toujours pas. Mangletooth a compté les jours. Puis Mangletooth a arrêté de compter. <grogne>", "Le contact des joyaux. Longtemps que Mangletooth n'en a pas tenu. Vous ne savez pas ce que c'est, quand on vous prive de votre pouvoir. Mangletooth espère que vous ne le saurez jamais.", "Mangletooth n'est pas un imbécile. Mangletooth est reconnaissant. Les deux. <grogne>" }, signoff = "Mangletooth\nCamp Taurajo" },
  [33] = { greeting = "$N,", body = { "Les gobelins abattent toujours les arbres de la Combe. Par vent d'ouest, je sens leur fumée jusqu'ici, à la frontière. Deux machines brisées ne leur apprendront rien, et je ne l'ai jamais cru.", "Mais la plupart des gémissements ont cessé. Pas le chagrin, les gémissements. Les esprits sont blessés, encore, et ils en ont bien le droit. Ils n'en sont plus aveuglés.", "Il se peut encore que les anciens doivent venir apaiser ce qui reste. Je vous l'ai déjà dit. Je vous le redis, pour que vous ne preniez jamais une victoire pour une forêt.", "Les esprits m'ont donné les marques de ces machines. Vous avez parlé à ces machines le seul langage que les gobelins comprennent. Je trouve le partage équitable." }, signoff = "Avec colère et avec espoir,\nSeereth Stonebreak" },
  [34] = { greeting = "$gChanceux:Chanceuse; $N,", body = { "Trente ! Trente précieux crânes, et tous plus beaux les uns que les autres ! Je les compte à chaque relève de la garde, au cas où l'un d'eux aurait roulé quelque part. Aucun n'a bougé. Ils sont très sages.", "Je les garde à l'abri des regards, là où Darthalia ne peut pas les voir. Elle estime qu'un Garde noir de service devrait monter la garde. C'est ce que je fais. Je les garde avec le plus grand soin.", "Il ne se passe jamais rien à ce poste. Pendant que vous vous amusiez comme jamais à Hautebrande, j'étais si jaloux que j'aurais pu tomber en morceaux, ce qui, à mon âge, est un vrai risque.", "J'espère bien que vous vous arrêterez à la porte en passant, ne serait-ce que pour que je puisse encore vous remercier." }, signoff = "Votre dévoué Garde noir,\nSamsa\nMoulin-de-Tarren" },
}
-- (the places Classic Era's client names otherwise, swapped in there)
ns.classicNames = { ["Hurlevent"] = "Stormwind", ["Cabestan"] = "Ratchet", ["Sabot-d’Hiver"] = "Winterhoof", ["Comté-du-Lac"] = "Lakeshire", ["Sombre-Comté"] = "Darkshire", ["Fossoyeuse"] = "Undercity", ["Hautebrande"] = "Hillsbrad" }
